from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parents[2]
path = '.github/workflows/admin-v2.yml'
part = 0
last = True
data = ''
cache = ROOT / ".phase2-payload" / (path.replace("/", "__") + ".b64")
cache.parent.mkdir(parents=True, exist_ok=True)
mode = "w" if part == 0 else "a"
with cache.open(mode) as handle:
    handle.write(data)
if last:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(cache.read_text()))
    cache.unlink()
